#!/usr/bin/env bash

set -o pipefail
cd /home/vela/openvela || exit 125
adb kill-server >/dev/null 2>&1 || true

(
  until adb -s emulator-5554 get-state >/dev/null 2>&1; do
    sleep 1
  done
  adb -s emulator-5554 emu redir add tcp:28789:28789 >/dev/null
) &

exec ./prebuilts/emulator/tools/emulator.sh cmake_out/vela_goldfish-arm64-v8a-ap-formation/ \
  -no-window \
  -no-audio \
  -no-snapshot \
  -gpu swiftshader_indirect \
  -accel off \
  >> /home/vela/openvela-formation-emulator.log 2>&1

import asyncio
import json

import websockets


async def main():
    async with websockets.connect("ws://127.0.0.1:28789") as websocket:
        challenge = json.loads(await websocket.recv())
        assert challenge["event"] == "connect.challenge"
        await websocket.send(json.dumps({
            "type": "message",
            "content": "现在四辆车都在线吗",
            "chat_id": "acceptance",
        }, ensure_ascii=False))
        while True:
            response = json.loads(await asyncio.wait_for(websocket.recv(), 30))
            if response.get("type") == "response":
                print(json.dumps(response, ensure_ascii=False))
                assert "四辆车中有4辆在线" in response["content"]
                return


asyncio.run(main())

from __future__ import annotations

import json
import re
import time
import uuid
from typing import Any


def _completion(message: dict[str, Any], finish_reason: str = "stop") -> dict[str, Any]:
    return {
        "id": f"chatcmpl-local-{uuid.uuid4().hex[:10]}",
        "object": "chat.completion",
        "created": int(time.time()),
        "model": "formation-local-stub",
        "choices": [{"index": 0, "message": message, "finish_reason": finish_reason}],
        "usage": {"prompt_tokens": 0, "completion_tokens": 0, "total_tokens": 0},
    }


def _tool_call(arguments: dict[str, Any]) -> dict[str, Any]:
    return _completion(
        {
            "role": "assistant",
            "content": None,
            "tool_calls": [
                {
                    "id": f"call_{uuid.uuid4().hex[:12]}",
                    "type": "function",
                    "function": {"name": "formation_control", "arguments": json.dumps(arguments, ensure_ascii=False)},
                }
            ],
        },
        "tool_calls",
    )


def _summarize_tool(content: str) -> str:
    try:
        data = json.loads(content)
    except (json.JSONDecodeError, TypeError):
        return f"实验服务返回：{content[:300]}"
    if not data.get("ok"):
        return f"操作未成功：{data.get('error', data)}"
    if "capabilities" in data:
        formations = "、".join(data["capabilities"].get("formations", []))
        modes = "、".join(data["capabilities"].get("control_modes", {}).keys())
        return f"本机编队服务可用，支持队形：{formations}；控制模式：{modes}。"
    exp = data.get("experiment") or {}
    state = exp.get("state", "UNKNOWN")
    exp_id = exp.get("experiment_id") or "当前实验"
    robots = exp.get("robots") or []
    online_count = sum(1 for robot in robots if robot.get("online"))
    if robots:
        robot_status = f"四辆车中有{online_count}辆在线"
