    /rosapi/topics 服务）通过 svc_q 队列拿响应。同时保留一个 extras 列表兜住    
    偶尔出现、没人等的响应消息，避免 asyncio.Queue 无界增长。
    """
    extras = []
    while True:
        try:
            raw = await asyncio.wait_for(ws.recv(), timeout=1.0)
        except asyncio.TimeoutError:
            continue
        except Exception:  # noqa: BLE001  连接断了就退出
            return
        try:
            d = json.loads(raw)
        except ValueError:
            continue

        # 非 /odom 的消息：可能是服务响应，转交给等待者
        if d.get("op") != "publish" or d.get("topic") != FEEDBACK_TOPIC:        
            if svc_q is not None and d.get("id"):
                try:
                    svc_q.put_nowait(d)
                except Exception:  # noqa: BLE001  队列满时丢最旧的
                    try:
                        extras.append(d)
                        del extras[:-16]
                    except Exception:  # noqa: BLE001
                        pass
            continue

        try:
            p = d["msg"]["pose"]["pose"]
            state["x"] = float(p["position"]["x"])
            state["y"] = float(p["position"]["y"])
            state["yaw"] = math.degrees(yaw_of(p.get("orientation")))
            state["n"] = state.get("n", 0) + 1
            state["t"] = time.time()
