# 所以直接发 /cmd_vel。改回桥接：--topic /app/cmd_vel
DEFAULT_TOPIC = "/cmd_vel"

# ---- 安全上限（超过就截断并提示）----
MAX_SPEED = 0.25          # m/s
MAX_ANGULAR = 1.0         # rad/s (~57°/s)
MAX_DISTANCE = 3.0        # m
MAX_ANGLE = 180.0         # deg
DEFAULT_SPEED = 0.15      # m/s
DEFAULT_ANGULAR_DEG = 40.0  # deg/s
