from __future__ import annotations

import threading
import time
import uuid
from dataclasses import asdict, dataclass
from typing import Any, Callable

from .simulator import FormationSimulator, LabError


TASK_STATES = {"pending", "running", "done", "blocked", "cancelled"}
ZONE_ASSIGNMENTS = {
    "entrance": {"primary": "Robot01", "backup": "Robot02"},
    "corridor": {"primary": "Robot02", "backup": "Robot01"},
    "exhibit": {"primary": "Robot03", "backup": "Robot04"},
    "device": {"primary": "Robot04", "backup": "Robot03"},
}


@dataclass
class Task:
    task_id: str
    zone: str
    robot_id: str
    route: str
    state: str
    reason: str
    created_at: float
    updated_at: float
    execution_mode: str
    formation_experiment_id: str | None = None

    def public(self) -> dict[str, Any]:
        return asdict(self)


class TaskService:
    def __init__(self, simulator: FormationSimulator):
        self.simulator = simulator
        self._lock = threading.RLock()
        self._tasks: dict[str, Task] = {}

    def capabilities(self) -> dict[str, Any]:
        return {
            "task_states": sorted(TASK_STATES),
            "zones": ZONE_ASSIGNMENTS,
            "actions": ["dispatch_task", "query_status", "cancel_task", "reassign_task"],
            "execution_modes": ["formation_simulation", "route_executor"],
            "route_executor": "unconfigured",
            "safety": {
                "offline_robot_dispatch": "rejected",
                "physical_route_blockage": "blocked_without_automatic_reassignment",
                "operator_cancel": "immediate_stop_when_active",
            },
        }

    def _robot(self, robot_id: str) -> dict[str, Any]:
        for robot in self.simulator.snapshot().get("robots", []):
            if robot.get("robot_id") == robot_id:
                return robot
        raise LabError(f"unknown robot_id: {robot_id}", code="unknown_robot")

    def _new_task(self, payload: dict[str, Any], robot_id: str) -> Task:
        now = time.time()
        return Task(
            task_id=str(payload.get("task_id") or f"task-{int(now)}-{uuid.uuid4().hex[:6]}"),
            zone=str(payload.get("zone", "")).strip().lower(),
            robot_id=robot_id,
            route=str(payload.get("route", "")).strip(),
            state="pending",
            reason="accepted",
            created_at=now,
            updated_at=now,
            execution_mode="route_executor",
        )

    def dispatch(self, payload: dict[str, Any]) -> dict[str, Any]:
        zone = str(payload.get("zone", "")).strip().lower()
        if zone not in ZONE_ASSIGNMENTS:
            raise LabError("zone must be entrance, corridor, exhibit, or device", code="unknown_zone")
        requested_robot = str(payload.get("robot_id", "")).strip()
        robot_id = requested_robot or ZONE_ASSIGNMENTS[zone]["primary"]
        if requested_robot not in ("", ZONE_ASSIGNMENTS[zone]["primary"], ZONE_ASSIGNMENTS[zone]["backup"]):
            raise LabError("robot is not assigned to this zone", code="zone_robot_mismatch")
        robot = self._robot(robot_id)
        if not robot.get("online"):
            raise LabError(f"{robot_id} is offline and cannot receive a task", code="robot_offline")
        task = self._new_task(payload, robot_id)
        with self._lock:
            previous = self._tasks.get(task.task_id)
            if previous:
                if previous.zone == task.zone and previous.robot_id == task.robot_id and previous.route == task.route:
                    return {"ok": True, "idempotent_replay": True, "task": previous.public()}
                raise LabError("task_id already exists with different parameters", status=409, code="task_id_conflict")
            execution = str(payload.get("execution", "route")).strip().lower()
            if execution == "formation":
                command = {
                    "action": "start",
                    "experiment_id": f"task-{task.task_id}",
                    "formation": str(payload.get("formation", "square")),
                    "spacing_m": float(payload.get("spacing_m", 0.8)),
                    "duration_s": float(payload.get("duration_s", 30.0)),
                    "control_mode": str(payload.get("control_mode", "anchored")),
                }
                result = self.simulator.handle_command(command)
                task.execution_mode = "formation_simulation"
                task.formation_experiment_id = result["experiment"]["experiment_id"]
                task.state = "running"
                task.reason = "formation_simulation_started"
            elif execution == "route":
                task.state = "blocked"
                task.reason = "route_executor_unconfigured"
            else:
                raise LabError("execution must be route or formation", code="unsupported_execution")
            task.updated_at = time.time()
            self._tasks[task.task_id] = task
            return {"ok": True, "task": task.public()}

    def status(self, task_id: str | None = None) -> dict[str, Any]:
        with self._lock:
            if task_id:
                task = self._tasks.get(task_id)
                if not task:
                    raise LabError("unknown task_id", code="unknown_task")
                self._refresh_task(task)
                return {"ok": True, "task": task.public()}
            for task in self._tasks.values():
                self._refresh_task(task)
            return {"ok": True, "tasks": [task.public() for task in self._tasks.values()]}

    def _refresh_task(self, task: Task) -> None:
        if task.state != "running" or not task.formation_experiment_id:
            return
        experiment = self.simulator.snapshot()
        current_id = experiment.get("experiment_id")
        if current_id != task.formation_experiment_id:
            return
        if experiment["state"] == "FINISHED":
            task.state = "done"
            task.reason = "formation_completed"
        elif experiment["state"] in ("FAILED", "ABORTED"):
            task.state = "blocked" if experiment["state"] == "FAILED" else "cancelled"
            task.reason = str(experiment.get("error_code") or experiment.get("message") or "formation_stopped")
        task.updated_at = time.time()

    def cancel(self, task_id: str, reason: str) -> dict[str, Any]:
        with self._lock:
            task = self._tasks.get(task_id)
            if not task:
                raise LabError("unknown task_id", code="unknown_task")
            if task.state in ("done", "cancelled"):
                return {"ok": True, "task": task.public()}
            if task.state == "running" and task.formation_experiment_id:
                self.simulator.handle_command({"action": "stop", "reason": reason})
            task.state = "cancelled"
            task.reason = reason[:120]
            task.updated_at = time.time()
            return {"ok": True, "task": task.public()}

    def reassign(self, task_id: str, robot_id: str, reason: str) -> dict[str, Any]:
        with self._lock:
            task = self._tasks.get(task_id)
            if not task:
                raise LabError("unknown task_id", code="unknown_task")
            if task.state not in ("pending", "blocked"):
                raise LabError("only pending or blocked tasks can be reassigned", status=409, code="task_not_reassignable")
            robot = self._robot(robot_id)
            if not robot.get("online"):
                raise LabError(f"{robot_id} is offline and cannot receive a task", code="robot_offline")
            assignment = ZONE_ASSIGNMENTS[task.zone]
            if robot_id not in (assignment["primary"], assignment["backup"]):
                raise LabError("robot is not assigned to this zone", code="zone_robot_mismatch")
            task.robot_id = robot_id
            task.state = "pending"
            task.reason = f"reassignment_pending: {reason[:100]}"
            task.updated_at = time.time()
            return {"ok": True, "task": task.public()}

