from __future__ import annotations

import argparse
import json
import time
import urllib.error
import urllib.request
from typing import Any


class M1ApiError(RuntimeError):
    pass


class M1FormationClient:
    def __init__(self, base_url: str, timeout_s: float = 3.0):
        self.base_url = base_url.rstrip("/")
        self.timeout_s = timeout_s

    def _request(self, method: str, path: str, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        body = None
        headers = {"Accept": "application/json"}
        if payload is not None:
            body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
            headers["Content-Type"] = "application/json"
        request = urllib.request.Request(self.base_url + path, data=body, headers=headers, method=method)
        try:
            with urllib.request.urlopen(request, timeout=self.timeout_s) as response:
                data = json.load(response)
        except (urllib.error.URLError, TimeoutError, json.JSONDecodeError) as exc:
            raise M1ApiError(f"M1 API request failed: {method} {path}: {exc}") from exc
        if not isinstance(data, dict):
            raise M1ApiError("M1 API response must be a JSON object")
        if data.get("ok") is False:
            error = data.get("error") or {}
            raise M1ApiError(str(error.get("message") or error or "M1 API rejected request"))
        return data

    def health(self) -> dict[str, Any]:
        return self._request("GET", "/api/v1/health")

    def capabilities(self) -> dict[str, Any]:
        return self._request("GET", "/api/v1/capabilities")

    def status(self) -> dict[str, Any]:
        return self._request("GET", "/api/v1/state")

    def dispatch_task(self, task: dict[str, Any]) -> dict[str, Any]:
        return self._request("POST", "/api/v1/tasks", task)

    def cancel_task(self, task_id: str, reason: str = "operator_cancel") -> dict[str, Any]:
        return self._request("POST", "/api/v1/tasks/cancel", {"task_id": task_id, "reason": reason})

    def reassign_task(self, task_id: str, robot_id: str, reason: str) -> dict[str, Any]:
        return self._request("POST", "/api/v1/tasks/reassign", {"task_id": task_id, "robot_id": robot_id, "reason": reason})


def main() -> None:
    parser = argparse.ArgumentParser(description="Check and exercise the M1 task API")
    parser.add_argument("--base-url", default="http://192.168.1.104:8765")
    args = parser.parse_args()
    client = M1FormationClient(args.base_url)
    print(json.dumps({"health": client.health(), "capabilities": client.capabilities(), "status": client.status()}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

from __future__ import annotations

import argparse
import json
import logging
import signal
import threading
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from urllib.parse import urlparse

from .llm_stub import create_chat_completion
from .simulator import FormationSimulator, LabError
from .task_service import TaskService


LOG = logging.getLogger("formation-lab")


class LabHTTPServer(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(self, address: tuple[str, int], handler: type[BaseHTTPRequestHandler], simulator: FormationSimulator, static_dir: Path):
        super().__init__(address, handler)
        self.simulator = simulator
        self.tasks = TaskService(simulator)
        self.static_dir = static_dir


class Handler(BaseHTTPRequestHandler):
    server: LabHTTPServer

    def log_message(self, fmt: str, *args: Any) -> None:
        LOG.info("%s - %s", self.client_address[0], fmt % args)

    def _send_json(self, status: int, data: dict[str, Any]) -> None:
        raw = json.dumps(data, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(raw)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("Access-Control-Allow-Origin", "*")
        self.end_headers()
        self.wfile.write(raw)

    def _send_file(self, path: Path, content_type: str) -> None:
        if not path.is_file():
            self.send_error(HTTPStatus.NOT_FOUND)
            return
        raw = path.read_bytes()
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(raw)))
        self.send_header("Cache-Control", "no-cache")
        self.end_headers()
        self.wfile.write(raw)

    def _body(self) -> dict[str, Any]:
        try:
            length = int(self.headers.get("Content-Length", "0"))
        except ValueError as exc:
            raise LabError("invalid Content-Length") from exc
        if length <= 0 or length > 64 * 1024:
            raise LabError("request body must be 1..65536 bytes")
        try:
            value = json.loads(self.rfile.read(length).decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise LabError("request body is not valid UTF-8 JSON") from exc
        if not isinstance(value, dict):
            raise LabError("JSON body must be an object")
        return value

    def do_OPTIONS(self) -> None:
        self.send_response(HTTPStatus.NO_CONTENT)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.end_headers()

    def do_GET(self) -> None:
        path = urlparse(self.path).path
        if path in ("/", "/index.html"):
            self._send_file(self.server.static_dir / "index.html", "text/html; charset=utf-8")
        elif path == "/api/v1/health":
            self._send_json(200, {"ok": True, "service": "formation-lab", "version": "0.1.0"})
        elif path == "/api/v1/capabilities":
            self._send_json(200, {"ok": True, "capabilities": self.server.simulator.capabilities()})
        elif path == "/api/v1/state":
            self._send_json(200, {"ok": True, "experiment": self.server.simulator.snapshot()})
        elif path == "/api/v1/tasks/capabilities":
            self._send_json(200, self.server.tasks.capabilities())
        elif path == "/api/v1/tasks":
            self._send_json(200, self.server.tasks.status())
        else:
            self.send_error(HTTPStatus.NOT_FOUND)

    def do_POST(self) -> None:
        path = urlparse(self.path).path
        try:
            payload = self._body()
            if path == "/api/v1/formation":
                response = self.server.simulator.handle_command(payload)
            elif path == "/api/v1/tasks":
                response = self.server.tasks.dispatch(payload)
            elif path == "/api/v1/tasks/status":
                response = self.server.tasks.status(payload.get("task_id"))
            elif path == "/api/v1/tasks/cancel":
                response = self.server.tasks.cancel(str(payload.get("task_id", "")), str(payload.get("reason") or "operator_cancel"))
            elif path == "/api/v1/tasks/reassign":
                response = self.server.tasks.reassign(str(payload.get("task_id", "")), str(payload.get("robot_id", "")), str(payload.get("reason") or "operator_reassign"))
            elif path in ("/v1/chat/completions", "/chat/completions"):
                response = create_chat_completion(payload)
            else:
                self.send_error(HTTPStatus.NOT_FOUND)
                return
            self._send_json(200, response)
        except LabError as exc:
            self._send_json(exc.status, {"ok": False, "error": {"code": exc.code, "message": str(exc)}})
        except Exception:
            LOG.exception("Unhandled request failure")
            self._send_json(500, {"ok": False, "error": {"code": "internal_error", "message": "internal service error"}})


def main() -> None:
    parser = argparse.ArgumentParser(description="Local openvela four-robot formation lab")
    parser.add_argument("--host", default="0.0.0.0")
    parser.add_argument("--port", type=int, default=8765)
    parser.add_argument("--data-dir", default="var/experiments")
    parser.add_argument("--time-scale", type=float, default=1.0)
    args = parser.parse_args()
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
    root = Path(__file__).resolve().parent.parent
    simulator = FormationSimulator((root / args.data_dir).resolve(), time_scale=args.time_scale)
    server = LabHTTPServer((args.host, args.port), Handler, simulator, root / "formation_lab" / "static")

    def stop_server(_signum: int, _frame: Any) -> None:
        threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, stop_server)
    signal.signal(signal.SIGINT, stop_server)
    LOG.info("Formation Lab listening on http://%s:%d", args.host, args.port)
    try:
        server.serve_forever(poll_interval=0.2)
    finally:
        simulator.close()
        server.server_close()


if __name__ == "__main__":
    main()

from __future__ import annotations

import threading
import time
import uuid
from dataclasses import asdict, dataclass
from typing import Any, Callable

from .simulator import FormationSimulator, LabError


TASK_STATES = {"pending", "running", "done", "blocked", "cancelled"}
ZONE_ASSIGNMENTS = {
    "entrance": {"primary": "Robot01", "backup": "Robot02"},
    "corridor": {"primary": "Robot02", "backup": "Robot01"},
    "exhibit": {"primary": "Robot03", "backup": "Robot04"},
    "device": {"primary": "Robot04", "backup": "Robot03"},
}


@dataclass
class Task:
    task_id: str
    zone: str
    robot_id: str
    route: str
    state: str
    reason: str
    created_at: float
    updated_at: float
    execution_mode: str
    formation_experiment_id: str | None = None

    def public(self) -> dict[str, Any]:
        return asdict(self)


class TaskService:
    def __init__(self, simulator: FormationSimulator):
        self.simulator = simulator
        self._lock = threading.RLock()
        self._tasks: dict[str, Task] = {}

    def capabilities(self) -> dict[str, Any]:
        return {
            "task_states": sorted(TASK_STATES),
            "zones": ZONE_ASSIGNMENTS,
            "actions": ["dispatch_task", "query_status", "cancel_task", "reassign_task"],
            "execution_modes": ["formation_simulation", "route_executor"],
            "route_executor": "unconfigured",
            "safety": {
                "offline_robot_dispatch": "rejected",
                "physical_route_blockage": "blocked_without_automatic_reassignment",
                "operator_cancel": "immediate_stop_when_active",
            },
        }

    def _robot(self, robot_id: str) -> dict[str, Any]:
        for robot in self.simulator.snapshot().get("robots", []):
            if robot.get("robot_id") == robot_id:
                return robot
        raise LabError(f"unknown robot_id: {robot_id}", code="unknown_robot")

    def _new_task(self, payload: dict[str, Any], robot_id: str) -> Task:
        now = time.time()
        return Task(
            task_id=str(payload.get("task_id") or f"task-{int(now)}-{uuid.uuid4().hex[:6]}"),
            zone=str(payload.get("zone", "")).strip().lower(),
            robot_id=robot_id,
            route=str(payload.get("route", "")).strip(),
            state="pending",
            reason="accepted",
            created_at=now,
            updated_at=now,
            execution_mode="route_executor",
        )

    def dispatch(self, payload: dict[str, Any]) -> dict[str, Any]:
        zone = str(payload.get("zone", "")).strip().lower()
        if zone not in ZONE_ASSIGNMENTS:
            raise LabError("zone must be entrance, corridor, exhibit, or device", code="unknown_zone")
        requested_robot = str(payload.get("robot_id", "")).strip()
        robot_id = requested_robot or ZONE_ASSIGNMENTS[zone]["primary"]
        if requested_robot not in ("", ZONE_ASSIGNMENTS[zone]["primary"], ZONE_ASSIGNMENTS[zone]["backup"]):
            raise LabError("robot is not assigned to this zone", code="zone_robot_mismatch")
        robot = self._robot(robot_id)
        if not robot.get("online"):
            raise LabError(f"{robot_id} is offline and cannot receive a task", code="robot_offline")
        task = self._new_task(payload, robot_id)
        with self._lock:
            previous = self._tasks.get(task.task_id)
            if previous:
                if previous.zone == task.zone and previous.robot_id == task.robot_id and previous.route == task.route:
                    return {"ok": True, "idempotent_replay": True, "task": previous.public()}
                raise LabError("task_id already exists with different parameters", status=409, code="task_id_conflict")
            execution = str(payload.get("execution", "route")).strip().lower()
            if execution == "formation":
                command = {
                    "action": "start",
                    "experiment_id": f"task-{task.task_id}",
                    "formation": str(payload.get("formation", "square")),
                    "spacing_m": float(payload.get("spacing_m", 0.8)),
                    "duration_s": float(payload.get("duration_s", 30.0)),
                    "control_mode": str(payload.get("control_mode", "anchored")),
                }
                result = self.simulator.handle_command(command)
                task.execution_mode = "formation_simulation"
                task.formation_experiment_id = result["experiment"]["experiment_id"]
                task.state = "running"
                task.reason = "formation_simulation_started"
            elif execution == "route":
                task.state = "blocked"
                task.reason = "route_executor_unconfigured"
            else:
                raise LabError("execution must be route or formation", code="unsupported_execution")
            task.updated_at = time.time()
            self._tasks[task.task_id] = task
            return {"ok": True, "task": task.public()}

    def status(self, task_id: str | None = None) -> dict[str, Any]:
        with self._lock:
            if task_id:
                task = self._tasks.get(task_id)
                if not task:
                    raise LabError("unknown task_id", code="unknown_task")
                self._refresh_task(task)
                return {"ok": True, "task": task.public()}
            for task in self._tasks.values():
                self._refresh_task(task)
            return {"ok": True, "tasks": [task.public() for task in self._tasks.values()]}

    def _refresh_task(self, task: Task) -> None:
        if task.state != "running" or not task.formation_experiment_id:
            return
        experiment = self.simulator.snapshot()
        current_id = experiment.get("experiment_id")
        if current_id != task.formation_experiment_id:
            return
        if experiment["state"] == "FINISHED":
            task.state = "done"
            task.reason = "formation_completed"
        elif experiment["state"] in ("FAILED", "ABORTED"):
            task.state = "blocked" if experiment["state"] == "FAILED" else "cancelled"
            task.reason = str(experiment.get("error_code") or experiment.get("message") or "formation_stopped")
        task.updated_at = time.time()

    def cancel(self, task_id: str, reason: str) -> dict[str, Any]:
        with self._lock:
            task = self._tasks.get(task_id)
            if not task:
                raise LabError("unknown task_id", code="unknown_task")
            if task.state in ("done", "cancelled"):
                return {"ok": True, "task": task.public()}
            if task.state == "running" and task.formation_experiment_id:
                self.simulator.handle_command({"action": "stop", "reason": reason})
            task.state = "cancelled"
            task.reason = reason[:120]
            task.updated_at = time.time()
            return {"ok": True, "task": task.public()}

    def reassign(self, task_id: str, robot_id: str, reason: str) -> dict[str, Any]:
        with self._lock:
            task = self._tasks.get(task_id)
            if not task:
                raise LabError("unknown task_id", code="unknown_task")
            if task.state not in ("pending", "blocked"):
                raise LabError("only pending or blocked tasks can be reassigned", status=409, code="task_not_reassignable")
            robot = self._robot(robot_id)
            if not robot.get("online"):
                raise LabError(f"{robot_id} is offline and cannot receive a task", code="robot_offline")
            assignment = ZONE_ASSIGNMENTS[task.zone]
            if robot_id not in (assignment["primary"], assignment["backup"]):
                raise LabError("robot is not assigned to this zone", code="zone_robot_mismatch")
            task.robot_id = robot_id
            task.state = "pending"
            task.reason = f"reassignment_pending: {reason[:100]}"
            task.updated_at = time.time()
            return {"ok": True, "task": task.public()}

