def save_wav(path: str, pcm: bytes, rate: int, channels: int) -> None:
    import wave
    with wave.open(path, "wb") as w:
        w.setnchannels(channels)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(bytes(pcm))


def to_asr_wav(src: str, dst: str, rate: int = 16000) -> bool:
    """把采集到的多通道 wav 转成单声道 16k，减小上传体积（ffmpeg 在板上已有）。"""
    if not shutil.which("ffmpeg"):
        return False
    rc = subprocess.call(["ffmpeg", "-hide_banner", "-loglevel", "error", "-y",
                          "-i", src, "-ar", str(rate), "-ac", "1", dst])
    return rc == 0


# ------------------------------------------------------------------ 识别（第2段）
def asr_transcribe(wav_path: str, args) -> tuple:
    """调云端 ASR，返回 (文本, 耗时秒)。"""
    cmd = [sys.executable, args.transcribe, wav_path, "--guard"]
    if args.language:
        cmd += ["--language", args.language]
    if args.timeout:
        cmd += ["--timeout", str(args.timeout)]
    env = dict(os.environ)
    env["PYTHONPATH"] = HERE + os.pathsep + env.get("PYTHONPATH", "")
    t0 = time.time()
    out = subprocess.run(cmd, capture_output=True, text=True, env=env, timeout=args.timeout + 30)
    cost = time.time() - t0
    if out.returncode != 0:
        raise RuntimeError("ASR 失败：%s" % (out.stderr.strip()[-400:] or out.stdout.strip()[-400:]))
    return out.stdout.strip(), cost


# ------------------------------------------------------------------ 下发（第4段）
def load_actions(path: str) -> dict:
    if path and os.path.isfile(path):
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    return {}


def render_action(action, parsed: dict) -> list:
    """把 action 定义（字符串或列表）渲染成 shell 命令。占位符 {formation} 等。

    注意：模板里的 shell 变量写法（如 $CAR_IP）不会被 .format() 影响，
    但 ${CAR_IP:-x} 这种会被当成格式化占位符并报 KeyError —— 踩过，已在
    vcmd_actions.json 里改成 $CAR_IP。
    """
    if action is None:
        return []
    items = [action] if isinstance(action, str) else list(action)
    out = []
    for item in items:
        try:
            out.append(item.format(**parsed.get("params", {}),
                                   **{"intent": parsed.get("intent", "")}))
        except (KeyError, IndexError, ValueError) as exc:
            # 模板写错时必须显式失败，不能默默打印一句就当成功
            out.append("__TEMPLATE_ERROR__%s" % exc)
    return out


def emit(parsed: dict, args, actions: dict) -> int:
    """第4段：执行或打印。返回退出码。

    退出码约定（调用方按这些判断，别改）：
      0 = 成功（dry-run 或执行成功）
      3 = 没解析出意图，未下发
      4 = 安全检查未通过，拒绝下发
      6 = 命令模板渲染失败，未下发
      7 = 意图有但命令表没配动作，--exec 下未下发
      8 = 动作执行了但返回非 0
    """
    failed = False
    intent = parsed.get("intent")
    if intent is None:
        print("[4/4] 没解析出意图，不下发", file=sys.stderr)
        return 3

    cmds = render_action(actions.get(intent), parsed)
    # 模板渲染失败必须显式报错，不能当成"执行成功"（踩过：只打印一句就返回 0）
    bad = [c for c in cmds if c.startswith("__TEMPLATE_ERROR__")]
    if bad:
        print("[4/4] ✗ 命令模板渲染失败，未下发：", file=sys.stderr)
        for c in bad:
            print("        %s" % c.replace("__TEMPLATE_ERROR__", ""), file=sys.stderr)
        print("        请检查 vcmd_actions.json 里 %s 的模板占位符" % intent, file=sys.stderr)
        return 6

    # 【新增】机器可读输出：让 voice_button 之类调用方不必解析人类可读文本，
    # 就能把"解析结果 + 实际下发的命令"记进日志，便于事后核对"语音 → 命令"对应关系。
    if getattr(args, "json_out", ""):
        try:
            with open(args.json_out, "w", encoding="utf-8") as f:
                json.dump({"intent": intent, "params": parsed.get("params", {}),
                           "defaults_applied": parsed.get("defaults_applied", []),
                           "commands": cmds, "executed": bool(args.exec)},
                          f, ensure_ascii=False)
        except OSError as exc:
            print("  写 %s 失败：%s" % (args.json_out, exc), file=sys.stderr)

    if args.json:
        print(json.dumps({"parsed": parsed, "commands": cmds, "dry_run": not args.exec},
                         ensure_ascii=False, indent=2))
    else:
        print("[4/4] 意图：%s" % intent)
        if parsed.get("params"):
            print("      参数：%s" % json.dumps(parsed["params"], ensure_ascii=False))
        if not cmds:
            # 意图识别出来了，但命令表里没配动作 -> 什么也没发生。
            # 这不能算成功：调用方（voice_button / 自动化脚本）会误以为已下发。
            # 用独立退出码 7 表示"未配置动作"，与 3(未识别)/4(安全拦截)/6(模板错) 区分开。
            print("      ✗ vcmd_actions.json 里没有给 %s 配命令，未下发任何东西" % intent,
                  file=sys.stderr)
            if args.exec:
                return 7
            # 非 --exec（dry-run）时只做提示，不算失败
            print("      （dry-run：没有动作可展示）")
            return 0
        # 【修复】模板里用 $ROBOTS 指定目标车（voice_button 会按识别出的车号设置），
        # 但 vcmd 单独运行时没人设置它 -> 多车命令会静默退化成单车。
        # 所以这里从解析结果里补上：robots=[1,2,3,4] -> ROBOTS=1,2,3,4
        run_env = dict(os.environ)
        rbs = (parsed.get("params") or {}).get("robots")
        if rbs and not run_env.get("ROBOTS"):
            try:
                run_env["ROBOTS"] = ",".join(str(int(x)) for x in rbs)
                print("      目标车 ROBOTS=%s" % run_env["ROBOTS"])
            except (TypeError, ValueError):
                pass
        for c in cmds:
            if args.exec:
                print("      执行：%s" % c)
                rc = subprocess.call(c, shell=True, env=run_env)
                print("        -> 退出码 %d" % rc)
                if rc != 0:
