            else:
                print("      dry-run：%s" % c)

    if args.out:
        with open(args.out, "w", encoding="utf-8") as f:
            json.dump({"parsed": parsed, "commands": cmds}, f, ensure_ascii=False, indent=2)
        print("      已写 %s" % args.out)
    return 8 if failed else 0


