      7 = 意图有但命令表没配动作，--exec 下未下发
      8 = 动作执行了但返回非 0
    """
    failed = False
    intent = parsed.get("intent")
    if intent is None:
        print("[4/4] 没解析出意图，不下发", file=sys.stderr)
        return 3

    cmds = render_action(actions.get(intent), parsed)
    # 模板渲染失败必须显式报错，不能当成"执行成功"（踩过：只打印一句就返回 0）
    bad = [c for c in cmds if c.startswith("__TEMPLATE_ERROR__")]
    if bad:
        print("[4/4] ✗ 命令模板渲染失败，未下发：", file=sys.stderr)
        for c in bad:
            print("        %s" % c.replace("__TEMPLATE_ERROR__", ""), file=sys.stderr)
        print("        请检查 vcmd_actions.json 里 %s 的模板占位符" % intent, file=sys.stderr)
        return 6

    # 【新增】机器可读输出：让 voice_button 之类调用方不必解析人类可读文本，
    # 就能把"解析结果 + 实际下发的命令"记进日志，便于事后核对"语音 → 命令"对应关系。
    if getattr(args, "json_out", ""):
        try:
            with open(args.json_out, "w", encoding="utf-8") as f:
                json.dump({"intent": intent, "params": parsed.get("params", {}),
                           "defaults_applied": parsed.get("defaults_applied", []),
                           "commands": cmds, "executed": bool(args.exec)},
                          f, ensure_ascii=False)
        except OSError as exc:
            print("  写 %s 失败：%s" % (args.json_out, exc), file=sys.stderr)

    if args.json:
        print(json.dumps({"parsed": parsed, "commands": cmds, "dry_run": not args.exec},
                         ensure_ascii=False, indent=2))
    else:
        print("[4/4] 意图：%s" % intent)
        if parsed.get("params"):
            print("      参数：%s" % json.dumps(parsed["params"], ensure_ascii=False))
        if not cmds:
            # 意图识别出来了，但命令表里没配动作 -> 什么也没发生。
            # 这不能算成功：调用方（voice_button / 自动化脚本）会误以为已下发。
            # 用独立退出码 7 表示"未配置动作"，与 3(未识别)/4(安全拦截)/6(模板错) 区分开。
            print("      ✗ vcmd_actions.json 里没有给 %s 配命令，未下发任何东西" % intent,
                  file=sys.stderr)
            if args.exec:
                return 7
            # 非 --exec（dry-run）时只做提示，不算失败
            print("      （dry-run：没有动作可展示）")
            return 0
        # 【修复】模板里用 $ROBOTS 指定目标车（voice_button 会按识别出的车号设置），
        # 但 vcmd 单独运行时没人设置它 -> 多车命令会静默退化成单车。
        # 所以这里从解析结果里补上：robots=[1,2,3,4] -> ROBOTS=1,2,3,4
        run_env = dict(os.environ)
        rbs = (parsed.get("params") or {}).get("robots")
        if rbs and not run_env.get("ROBOTS"):
            try:
                run_env["ROBOTS"] = ",".join(str(int(x)) for x in rbs)
                print("      目标车 ROBOTS=%s" % run_env["ROBOTS"])
            except (TypeError, ValueError):
                pass
        for c in cmds:
            if args.exec:
                print("      执行：%s" % c)
                rc = subprocess.call(c, shell=True, env=run_env)
                print("        -> 退出码 %d" % rc)
                if rc != 0:
                    failed = True
            else:
                print("      dry-run：%s" % c)

    if args.out:
        with open(args.out, "w", encoding="utf-8") as f:
            json.dump({"parsed": parsed, "commands": cmds}, f, ensure_ascii=False, indent=2)
        print("      已写 %s" % args.out)
    return 8 if failed else 0


