def save_wav(path: str, pcm: bytes, rate: int, channels: int) -> None:
    import wave
    with wave.open(path, "wb") as w:
        w.setnchannels(channels)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(bytes(pcm))


def to_asr_wav(src: str, dst: str, rate: int = 16000) -> bool:
    """把采集到的多通道 wav 转成单声道 16k，减小上传体积（ffmpeg 在板上已有）。"""
    if not shutil.which("ffmpeg"):
        return False
    rc = subprocess.call(["ffmpeg", "-hide_banner", "-loglevel", "error", "-y",
                          "-i", src, "-ar", str(rate), "-ac", "1", dst])
    return rc == 0


