def asr_transcribe(wav_path: str, args) -> tuple:
    """调云端 ASR，返回 (文本, 耗时秒)。"""
    cmd = [sys.executable, args.transcribe, wav_path, "--guard"]
    if args.language:
        cmd += ["--language", args.language]
    if args.timeout:
        cmd += ["--timeout", str(args.timeout)]
    env = dict(os.environ)
    env["PYTHONPATH"] = HERE + os.pathsep + env.get("PYTHONPATH", "")
    t0 = time.time()
    out = subprocess.run(cmd, capture_output=True, text=True, env=env, timeout=args.timeout + 30)
    cost = time.time() - t0
    if out.returncode != 0:
        raise RuntimeError("ASR 失败：%s" % (out.stderr.strip()[-400:] or out.stdout.strip()[-400:]))
    return out.stdout.strip(), cost


