def load_actions(path: str) -> dict:
    if path and os.path.isfile(path):
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    return {}


def render_action(action, parsed: dict) -> list:
    """把 action 定义（字符串或列表）渲染成 shell 命令。占位符 {formation} 等。

    注意：模板里的 shell 变量写法（如 $CAR_IP）不会被 .format() 影响，
    但 ${CAR_IP:-x} 这种会被当成格式化占位符并报 KeyError —— 踩过，已在
    vcmd_actions.json 里改成 $CAR_IP。
    """
    if action is None:
        return []
    items = [action] if isinstance(action, str) else list(action)
    out = []
    for item in items:
        try:
            out.append(item.format(**parsed.get("params", {}),
                                   **{"intent": parsed.get("intent", "")}))
        except (KeyError, IndexError, ValueError) as exc:
            # 模板写错时必须显式失败，不能默默打印一句就当成功
            out.append("__TEMPLATE_ERROR__%s" % exc)
    return out


