class RequestError(Exception):
    def __init__(self, message: str, status: int = 400, code: str = "invalid_request"):
        super().__init__(message)
        self.status = status
        self.code = code


STATE: dict[str, Any] = {
    "job_id": None,
    "state": "idle",
    "started_at": None,
    "finished_at": None,
    "exit_code": None,
    "request": None,
