async def do_job(args, params):
    url = "ws://%s:%d" % (args.car[0], args.port)
    async with websockets.connect(url, open_timeout=8, max_size=2 ** 22) as ws:
        print("已连上 %s" % url)
        cmd = args.cmd

        # 订阅 /odom 拿反馈（除非显式 --no-feedback）
        state = {"x": 0.0, "y": 0.0, "yaw": 0.0, "n": 0, "scan": None, "scan_n": 0}
        # 服务响应的旁路队列：odom_reader 是唯一的 recv() 者，其它人从这里拿消息
        svc_q = asyncio.Queue()
        use_feedback = not getattr(args, "no_feedback", False)
        await ws.send(json.dumps({"op": "subscribe", "topic": LIDAR_TOPIC, "id": "lidar"}))
        reader = asyncio.create_task(odom_reader(ws, state, svc_q))
        if use_feedback:
            await ws.send(json.dumps({"op": "subscribe",
                                      "topic": FEEDBACK_TOPIC, "id": "odom"}))
            for _ in range(20):
                if state["n"] > 0:
                    break
                await asyncio.sleep(0.1)
            if state["n"] == 0:
                print("  ⚠ 2 秒内没收到 /odom，退回开环控制")
                use_feedback = False
                reader.cancel()
                reader = None
            else:
                n1 = state["n"]
                t1 = time.time()
                await asyncio.sleep(1.0)
                rate = (state["n"] - n1) / max(time.time() - t1, 1e-6)
                print("  反馈就绪：odom %.1f Hz，当前 yaw=%.1f°" % (rate, state["yaw"]))

        if cmd in ("FORWARD", "BACKWARD", "STRAFE_LEFT", "STRAFE_RIGHT", "TURN_LEFT", "TURN_RIGHT"):
            for _ in range(30):
                if state.get("scan_n", 0) > 0:
                    break
                await asyncio.sleep(0.1)
            rejection = motion_rejection(cmd, params, state)
            if rejection:
                for _ in range(3):
                    await publish(ws, args.topic, 0.0, 0.0, 0.0)
                    await asyncio.sleep(0.05)
                print("@@SPEAK@@%s" % rejection)
                print("运动指令已拒绝：%s" % rejection)
                return 9

        if cmd == "STOP":
            await run_for(ws, args.topic, 0.0, 0.0, 0.3)
            print("已发送停止（零速度）")
            return 0

        if cmd in ("RESET", "CONFIRM"):
            await run_for(ws, args.topic, 0.0, 0.0, 0.3)
            print("已发送零速度（%s）" % cmd)
            return 0

        if cmd == "STATUS":
            if reader is None:
                # --no-feedback 时没有读取者，队列不会被填充，别白等 10 秒。
                # 能连上 rosbridge 本身就已经说明车在线。
                print("小车在线（已连上 rosbridge，未启用反馈故不查话题）")
                return 0
            await ws.send(json.dumps({"op": "call_service",
                                      "service": "/rosapi/topics",
                                      "args": {}, "id": "s1"}))
            # 【修法】不再自己 recv()，而是等 odom_reader 把 id=="s1" 的响应投进队列。
            # 原来这里直接 await ws.recv() 会和 odom_reader 抢同一个 WebSocket，
            # 报 "cannot call recv while another coroutine is already waiting"。
            got = False
            for _ in range(100):                     # 最多 10 秒
                try:
                    data = await asyncio.wait_for(svc_q.get(), timeout=0.1)
                except asyncio.TimeoutError:
                    continue
                if data.get("id") != "s1":
                    continue
                if data.get("result") is False or data.get("error"):
                    print("小车在线，但 /rosapi/topics 调用失败：%s"
                          % (data.get("error") or data.get("result")))
                    return 0
                vals = data.get("values") or {}
                topics = vals.get("topics") or []
                got = True
                print("小车在线，ROS 话题数 %d，控制话题 %s" % (len(topics), args.topic))
                break
            if not got:
                # 拿不到 rosapi 响应也不该算失败：至少连接是通的
                print("小车在线（已连上 rosbridge），但 10 秒内没等到 /rosapi/topics 响应")
                print("  提示：若该车没装 rosapi 节点，这是正常的；连接本身是通的")
            return 0

        if cmd == "FORWARD" or cmd == "BACKWARD":
            dist = float(params.get("distance_m", 0.5))
            speed = clamp(float(params.get("speed", DEFAULT_SPEED)), 0.05, MAX_SPEED)
            if use_feedback:
                kind = "forward" if cmd == "FORWARD" else "backward"
                print("%s：%.2f m（里程计闭环，巡航 %.2f m/s）" % (cmd, dist, speed))
                ok, done = await closed_loop(ws, state, args.topic, kind, dist, speed,
                                             abs(dist) / speed + MOVE_TIMEOUT_MARGIN)
                print("  实际完成 %.3f m%s" % (done, "" if ok else "（未收敛）"))
                return 0 if ok else 8
            vx = speed if cmd == "FORWARD" else -speed
            secs = abs(dist) / speed
            print("%s：%.2f m（开环），速度 %.2f m/s，用时 %.1f s" % (cmd, dist, speed, secs))
            await run_for(ws, args.topic, vx, 0.0, secs)
            print("完成，已停止")
            return 0

        if cmd in ("TURN_LEFT", "TURN_RIGHT"):
            deg = float(params.get("angle_deg", 45.0))
            if deg > MAX_ANGLE:
                print("角度 %.0f° 超过上限 %.0f°，已截断" % (deg, MAX_ANGLE))
                deg = MAX_ANGLE
            sign = 1.0 if cmd == "TURN_LEFT" else -1.0
            if use_feedback:
                print("%s：%.0f°（里程计闭环）" % (cmd, deg))
                ok, done = await closed_loop(ws, state, args.topic, "turn",
                                             sign * deg, ANG_MAX,
                                             deg / DEFAULT_ANGULAR_DEG * 3.0
                                             + MOVE_TIMEOUT_MARGIN)
